using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Common;
using PeopleHub.Application.Modules.Attendance;
using PeopleHub.Application.Modules.Employees;
using PeopleHub.Application.Modules.Leave;
using PeopleHub.Application.Modules.Payroll;
using PeopleHub.Application.Modules.Requests;
using PeopleHub.Domain.Entities;
namespace PeopleHub.Tests;
public class BusinessFoundationTests
{
 class User(string email="tester@example.local",bool financial=true):ICurrentUser { public string Email=>email;public int? EmployeeId=>6;public int UserId=>1;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>true;public bool Can(string p)=>financial||p is not(Perm.EmpPay or Perm.EmpSalary or Perm.EmpBankEdit or Perm.EmpIdentity or Perm.EmpBank); }
 static async Task<AppDbContext> Db(){var d=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.MigrateAsync();await SeedData.InitializeAsync(d,"Admin123!","Demo123!",new DateTime(2026,11,24));return d;}
 static PayrollService Pay(AppDbContext d,User u){var c=new AppClock(TimeProvider.System);var a=new AuditService(d,u,c);var n=new NotificationService(d,u,c);return new(d,u,a,n,new AttendanceService(d,new AccessScope(d,u),u,a,n,c,new WorkflowService(d,u,a)),c);}
 static LeaveService Leave(AppDbContext d,User u){var c=new AppClock(TimeProvider.System);var a=new AuditService(d,u,c);return new(d,new AccessScope(d,u),u,a,new NotificationService(d,u,c),c,new WorkflowService(d,u,a));}
 [Fact]public async Task CalculationSnapshotsSurviveRecalculation(){await using var d=await Db();var p=Pay(d,new());var id=await p.CreateAsync(2027,5);var first=await d.Set<PayrollCalculationSnapshot>().SingleAsync();var hash=first.Sha256;await p.RecalculateAsync(id);Assert.Equal(3,await d.Set<PayrollCalculationSnapshot>().CountAsync());Assert.Equal(hash,(await d.Set<PayrollCalculationSnapshot>().OrderBy(x=>x.Id).FirstAsync()).Sha256);Assert.Equal(64,hash.Length);}
 [Fact]public async Task FinalApproverCannotBeCreator(){await using var d=await Db();var p=Pay(d,new());var id=await p.CreateAsync(2027,5);await p.ReviewAsync(id);await p.FinanceApproveAsync(id);await Assert.ThrowsAsync<DomainException>(()=>p.FinalizeAsync(id));Assert.Equal(PayrollStatus.FinanceApproved,(await d.Set<PayrollRun>().FindAsync(id))!.Status);}
 [Fact]public async Task FinalRunCannotReopen(){await using var d=await Db();var p=Pay(d,new());var id=await p.CreateAsync(2027,5);await p.ReviewAsync(id);await p.FinanceApproveAsync(id);await Pay(d,new("approver@example.local")).FinalizeAsync(id);await Assert.ThrowsAsync<DomainException>(()=>p.ReopenAsync(id,"try"));await Assert.ThrowsAsync<DomainException>(()=>p.RecalculateAsync(id));}
 [Fact]public async Task BankFileUsesCalculationIdentityAndAccount(){await using var d=await Db();var p=Pay(d,new());var id=await p.CreateAsync(2027,5);var line=await d.Set<PayrollLine>().FirstAsync(l=>l.RunId==id);var old=line.EmployeeNameSnapshot;var bank=line.IbanSnapshot;line.Employee!.FullName="CHANGED";line.Employee.Iban="CHANGED-BANK";await d.SaveAsync();await p.ReviewAsync(id);await p.FinanceApproveAsync(id);await Pay(d,new("approver@example.local")).FinalizeAsync(id);var csv=await p.BankFileAsync(id);Assert.Contains(old,csv);Assert.DoesNotContain("CHANGED",csv);}
 [Theory][InlineData("snapshot")][InlineData("ledger")][InlineData("audit")]
 public async Task EvidenceIsAppendOnly(string kind){await using var d=await Db();if(kind=="snapshot"){var id=await Pay(d,new()).CreateAsync(2027,5);(await d.Set<PayrollCalculationSnapshot>().FirstAsync()).Payload="tampered";}else if(kind=="ledger"){d.Add(new LeaveTransaction{Reason="original"});await d.SaveAsync();(await d.Set<LeaveTransaction>().SingleAsync()).Reason="tampered";}else{d.Add(new AuditLog{Details="original"});await d.SaveAsync();(await d.Set<AuditLog>().FirstAsync()).Details="tampered";}await Assert.ThrowsAsync<InvalidOperationException>(()=>d.SaveAsync());}
 [Fact]public async Task HRSpecialistEditCannotOverwritePayFields(){await using var d=await Db();var u=new User(financial:false);var c=new AppClock(TimeProvider.System);var svc=new EmployeeService(d,new AccessScope(d,u),u,new AuditService(d,u,c),c);var original=await d.Set<Employee>().FirstAsync(x=>x.Id==6);var salary=original.BasicSalary;var bank=original.Iban;var insurance=original.InsuranceNumber;var model=System.Text.Json.JsonSerializer.Deserialize<Employee>(System.Text.Json.JsonSerializer.Serialize(original))!;model.NationalId="";model.BasicSalary=999999;model.Iban="OVERRIDE";model.BankName="OVERRIDE";model.InsuranceNumber="";await svc.SaveAsync(model,"test");Assert.Equal(salary,original.BasicSalary);Assert.Equal(bank,original.Iban);Assert.Equal(insurance,original.InsuranceNumber);}
 [Fact]public async Task AssignmentChangePreservesPreviousSalaryAndDepartment(){await using var d=await Db();var u=new User();var c=new AppClock(TimeProvider.System);var svc=new EmployeeService(d,new AccessScope(d,u),u,new AuditService(d,u,c),c);var original=await d.Set<Employee>().FirstAsync(x=>x.Id==6);var salary=original.BasicSalary;var model=System.Text.Json.JsonSerializer.Deserialize<Employee>(System.Text.Json.JsonSerializer.Serialize(original))!;model.NationalId="";model.BasicSalary+=100;await svc.SaveAsync(model,"Fictional history test");var rows=await d.Set<EmployeeAssignment>().Where(x=>x.EmployeeId==6).OrderBy(x=>x.Id).ToListAsync();Assert.Equal(2,rows.Count);Assert.Equal(salary,rows[0].BasicSalary);Assert.Equal(salary+100,rows[1].BasicSalary);Assert.Equal(rows[0].EffectiveTo,rows[1].EffectiveFrom);}
 [Fact]public async Task LeaveAdjustmentLedgerMatchesBalanceDelta(){await using var d=await Db();var l=Leave(d,new());var b=(await l.BalancesAsync(6,2027)).First();var before=b.Remaining;await l.AdjustBalanceAsync(6,b.LeaveTypeId,2027,b.Entitled+2,"Fictional ledger test");var rows=await d.Set<LeaveTransaction>().Where(x=>x.EmployeeId==6&&x.Year==2027&&x.LeaveTypeId==b.LeaveTypeId).ToListAsync();Assert.Equal(b.Remaining,rows.Sum(x=>x.Delta));Assert.Equal(before+2,b.Remaining);}
 [Fact]public async Task ApprovedCancellationRequiresReasonAndCannotRepeat(){await using var d=await Db();var u=new User();var l=Leave(d,u);var b=(await l.BalancesAsync(6,2027)).First();var req=new LeaveRequest{EmployeeId=6,LeaveTypeId=b.LeaveTypeId,LeaveType=b.LeaveType,StartDate=new(2027,6,1),EndDate=new(2027,6,1),Days=1,Status=RequestStatus.Approved};d.Add(req);b.Used+=1;await d.SaveAsync();await Assert.ThrowsAsync<DomainException>(()=>l.CancelApprovedAsync(req.Id));await l.CancelApprovedAsync(req.Id,"Fictional cancellation");await Assert.ThrowsAsync<DomainException>(()=>l.CancelApprovedAsync(req.Id,"repeat"));Assert.Equal(RequestStatus.Cancelled,(await d.Set<LeaveRequest>().FindAsync(req.Id))!.Status);Assert.Equal(1,await d.Set<LeaveTransaction>().CountAsync(x=>x.RequestId==req.Id&&x.Kind=="Cancellation"));}
}
